package com.clearchoice;
import android.app.*;import android.os.*;import android.content.*;import android.accessibilityservice.*;import android.view.accessibility.*;import android.graphics.Bitmap;import java.io.*;import java.util.*;
public class FlowInstrumentation extends Instrumentation {
 UiAutomation ui;StringBuilder report=new StringBuilder();File out;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{ui=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;ui.setServiceInfo(info);shell("settings delete secure enabled_accessibility_services");Thread.sleep(600);shell("settings put secure enabled_accessibility_services com.clearchoice/com.clearchoice.ClearChoiceService");Thread.sleep(1600);out=new File(getTargetContext().getExternalFilesDir(null),"qa");out.mkdirs();getTargetContext().startActivity(new Intent().setComponent(new ComponentName("com.demoshop","com.demoshop.ShopActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2000);require("com.clearchoice","◈ ClearChoice");shot("listing");click("com.clearchoice","Next products — scroll original",0);Thread.sleep(700);click("com.clearchoice","Next products — scroll original",0);Thread.sleep(700);require("com.clearchoice","▧   Reading Light");shot("catalog-end");click("com.clearchoice","Shop",0);Thread.sleep(700);click("com.clearchoice","Show original store",0);Thread.sleep(400);require("com.demoshop","Good finds, clear prices");shot("original");ui.executeShellCommand("input keyevent HOME").close();Thread.sleep(700);getTargetContext().startActivity(new Intent().setComponent(new ComponentName("com.demoshop","com.demoshop.ShopActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1000);require("com.clearchoice","◈ ClearChoice");click("com.clearchoice","View details",1);Thread.sleep(1500);require("com.demoshop","SCREEN:PRODUCT");shot("product");click("com.clearchoice","Select size",0);Thread.sleep(500);click("com.demoshop","Medium",0);Thread.sleep(1200);click("com.clearchoice","Select color",0);Thread.sleep(500);click("com.demoshop","Sage",0);Thread.sleep(1200);shot("variants");click("com.clearchoice","Add to cart",0);Thread.sleep(1800);require("com.demoshop","Cart (1)");shot("cart");click("com.clearchoice","Continue to checkout",0);Thread.sleep(1000);require("com.demoshop","Demo checkout");shot("protected");report.append("PASS core source overlay actions and exact cart count\n");result.putString("result",report.toString());finish(0,result);}catch(Throwable e){report.append("FAIL ").append(e.toString());try{shot("failure");}catch(Exception ignored){}result.putString("result",report.toString());finish(1,result);}finally{if(out!=null)try(FileWriter w=new FileWriter(new File(out,"report.txt"))){w.write(report.toString());}catch(Exception ignored){}}}
 void shell(String command)throws Exception{android.os.ParcelFileDescriptor fd=ui.executeShellCommand(command);try(java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 List<AccessibilityNodeInfo> roots(String pkg){ArrayList<AccessibilityNodeInfo> a=new ArrayList<>();for(AccessibilityWindowInfo w:ui.getWindows()){AccessibilityNodeInfo r=w.getRoot();if(r!=null&&pkg.equals(String.valueOf(r.getPackageName())))a.add(r);}return a;}
 void gather(AccessibilityNodeInfo n,String text,List<AccessibilityNodeInfo> found){if(n==null)return;String t=String.valueOf(n.getText()),d=String.valueOf(n.getContentDescription());if(text.equalsIgnoreCase(t)||text.equalsIgnoreCase(d))found.add(n);for(int i=0;i<n.getChildCount();i++)gather(n.getChild(i),text,found);}
 void require(String pkg,String text)throws Exception{for(int k=0;k<20;k++){ArrayList<AccessibilityNodeInfo> f=new ArrayList<>();for(AccessibilityNodeInfo r:roots(pkg))gather(r,text,f);if(!f.isEmpty()){report.append("observed ").append(text).append('\n');return;}Thread.sleep(250);}throw new AssertionError("Missing "+pkg+": "+text);}
 void click(String pkg,String text,int index)throws Exception{for(int k=0;k<15;k++){ArrayList<AccessibilityNodeInfo> f=new ArrayList<>();for(AccessibilityNodeInfo r:roots(pkg))gather(r,text,f);ArrayList<AccessibilityNodeInfo> clickable=new ArrayList<>();for(AccessibilityNodeInfo n:f)if(n.isClickable()&&n.isVisibleToUser())clickable.add(n);if(clickable.size()>index){if(!clickable.get(index).performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Rejected "+text);if(text.equals("Add to cart")){clickable.get(index).performAction(AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(1000);clickable.get(index).performAction(AccessibilityNodeInfo.ACTION_CLICK);report.append("duplicate and stale Add node attempted; expected count remains one\n");}report.append("clicked ").append(text).append('\n');return;}for(AccessibilityNodeInfo r:roots(pkg))scroll(r);Thread.sleep(250);}throw new AssertionError("Missing action "+text);}
 boolean scroll(AccessibilityNodeInfo n){if(n.isScrollable()&&n.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD))return true;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null&&scroll(c))return true;}return false;}
 void shot(String name)throws Exception{Bitmap b=ui.takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(out,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}}
}
